/**
 * Every edition in the essay contest archive, transcribed from the series hubs
 * on the live site (test-usni3.pantheonsite.io, captured 13 August 2026).
 *
 * These are teaser records, not pages: the archive listing renders them as
 * cards that don't navigate anywhere, so only the card's own fields are here.
 * `seriesSlug` matches `essayContestSeries` in `essayContests.ts`, which is what
 * the archive's Categories facet filters on.
 *
 * `image` is a filename in `assets/images/essay-archive/`, resolved through the
 * glob in `archiveImage()` rather than 150-odd individual imports. A leading
 * `../` escapes that folder for the handful reusing an existing asset.
 */

export interface EssayArchiveEntry {
  seriesSlug: string
  title: string
  year: string
  /** Funding or sponsorship credit, as shown on the live teaser. */
  author?: string
  summary?: string
  deadline?: string
  deadlineISO?: string
  image?: string
  imageAlt?: string
  /** Path on the live site this teaser came from. Kept for provenance. */
  sourceHref: string
}

const archiveImages = import.meta.glob('../assets/images/essay-archive/*', {
  eager: true,
  query: '?url',
  import: 'default',
}) as Record<string, string>

// The three 2026 teaser derivatives 404 on the live site, so these entries point
// at the same art already in the repo. Imported by name rather than globbed —
// an eager glob over the whole image folder would bundle all of it.
import generalPrize2026 from '../assets/images/essay-contest-general-prize-2026.webp'
import photoContest2026 from '../assets/images/essay-contest-photo-2026.jpg'
import navalIntelHero from '../assets/images/Naval Intel EC hero_2025.jpg'

const extraImages: Record<string, string> = {
  'essay-contest-general-prize-2026.webp': generalPrize2026,
  'essay-contest-photo-2026.jpg': photoContest2026,
  'Naval Intel EC hero_2025.jpg': navalIntelHero,
}

/** Resolve an entry's `image` filename to a bundled asset URL. */
export function archiveImage(name?: string): string | undefined {
  if (!name) return undefined
  if (name.startsWith('../')) return extraImages[name.slice(3)]
  return archiveImages[`../assets/images/essay-archive/${name}`]
}

